MultiLanguageSpellData['mx'][165718] = {name = "Palabra de poder: escudo", additional_info = "110 maná Alcance de 40 m\nInstante\n[q]Envuelve a un aliado en un escudo que dura hasta 30 s y absorbe daño. El daño recibido no interrumpe la canalización de hechizos."}
MultiLanguageSpellData['mx'][165719] = {name = "Nova Sagrada", additional_info = "15 maná\nInstante\n[q]Provoca una explosión de Luz Sagrada alrededor del taumaturgo que inflige 147 p. de daño Sagrado a todos los objetivos enemigos en un radio de 10 m y sana 3 p. a todos los miembros del grupo en un radio de 10 m. Estos efectos no generan amenaza."}
MultiLanguageSpellData['mx'][165720] = {name = "Fuego interno", additional_info = "14% del maná base\nInstante\n[q]Una ráfaga de energía Sagrada colma al taumaturgo, lo que aumenta su armadura un 10% y su poder con hechizos un 10%."}
MultiLanguageSpellData['mx'][165721] = {name = "Penitencia", additional_info = "Alcance de 30 m\nCanalizado (Hechizo de 3 seg)\n[q]Lanza una salva de luz Sagrada al objetivo, lo que inflige 100 p. de daño Sagrado a un enemigo cada 1 s durante 3 s."}
MultiLanguageSpellData['mx'][165722] = {name = "Sed de sangre", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {10 seg de reutilización}\nRequiere Arma cuerpo a cuerpo\n[q]Ataca instantáneamente al objetivo, lo que inflige un 120% de daño con arma normal. Además, los ataques cuerpo a cuerpo que alcancen al objetivo restaurarán un 1% de salud máxima. Este efecto dura 10 s."}
MultiLanguageSpellData['mx'][165723] = {name = "Grito de batalla", additional_info = "Instante\n[q]Aumenta el poder de ataque cuerpo a cuerpo de los objetivos amistosos cercanos durante 2 min."}
