MultiLanguageSpellData['mx'][165735] = {name = "Armadura vil", additional_info = "28% del maná base\nInstante\n[q]Rodea al taumaturgo con energía vil, lo que aumenta el poder con hechizos un 10%. Además, recuperas un 2% de tu salud máxima cada 5 s. Solo se puede tener un hechizo de armadura activo a la vez. Dura 30 min."}
