MultiLanguageSpellData['mx'][165739] = {name = "Palabra de poder: entereza", additional_info = "Alcance de 30 m\nInstante\n[q]Imbuye de vitalidad al objetivo, lo que aumenta un 10% su aguante durante 1 h.\n\n Si el objetivo pertenece a tu grupo o banda, afectará a todos los miembros del grupo o banda."}
