MultiLanguageSpellData['mx'][165742] = {name = "Ventisca", additional_info = "35 maná Alcance de 30 m\nHechizo de 2 seg\n[q]Invoca una ventisca que dura 8 s, lo que inflige daño de Escarcha cada 2 s a todos los enemigos de un área seleccionada."}
MultiLanguageSpellData['mx'][165743] = {name = "Armadura de Escarcha", additional_info = "{Instante} {10 seg de reutilización}\n[q]Reviste al taumaturgo con una capa de Escarcha que dura 30 min. El hielo espeso aumenta la armadura, ralentiza el movimiento de los atacantes cuerpo a cuerpo y aumenta el tiempo entre los ataques."}
MultiLanguageSpellData['mx'][165744] = {name = "Tormenta divina", additional_info = "{20% del maná base} {Alcance de ataques cuerpo a cuerpo}\nInstante\n[q]Un ataque con arma instantáneo que inflige daño Sagrado a un máximo de 4 enemigos en un radio de 8 m."}
MultiLanguageSpellData['mx'][165745] = {name = "Sello de Verdad", additional_info = "14% del maná base\nInstante\n[q]Colma al paladín de Poder Sagrado, lo que provoca que los ataques contra un solo objetivo apliquen Censura. Esto inflige [(0.01 * Poder con Hechizos + 0.0193 * Poder de ataque) * 5 */ 100] p. de daño Sagrado extra durante 5 min. Censura se puede acumular hasta 0 veces. Cuando se haya acumulado 0 veces, cada uno de los ataques del paladín también infligirá un 0% de daño con arma como daño Sagrado extra. Un paladín solo puede tener un sello activo a la vez. Dura 5 min.\n\n Desatar la energía de este sello infligirá (1 + 0.223 * Poder con Hechizos + 0.142 * Poder de ataque) p. de daño Sagrado a un enemigo, aumentado un 10% por cada aplicación de Censura sobre el objetivo."}
MultiLanguageSpellData['mx'][165746] = {name = "Aura de reprensión", additional_info = "Instante\n[q]Inflige daño Sagrado a cualquier criatura que golpee al taumaturgo."}
MultiLanguageSpellData['mx'][165747] = {name = "Bendición de poderío", additional_info = "Alcance de 30 m\nInstante\n[q]Da a un objetivo amistoso una Bendición que aumenta un 10% su poder de ataque y un 10% su poder de ataque a distancia y restaura un 1% de maná cada 5 s durante 5 min."}
MultiLanguageSpellData['mx'][165748] = {name = "Grito desmoralizador", additional_info = "Instante\n[q]Reduce el poder de ataque cuerpo a cuerpo de los enemigos cercanos durante 20 s."}
MultiLanguageSpellData['mx'][165749] = {name = "Atronar", additional_info = "Instante\n[q]Inflige daño de Naturaleza a los enemigos cercanos, lo que aumenta el tiempo entre sus ataques y ralentiza su velocidad de movimiento durante 6 s."}
MultiLanguageSpellData['mx'][165750] = {name = "Grito de orden", additional_info = "Instante\n[q]Aumenta un 10% la salud máxima de todos los miembros del grupo situados en un radio de 20 m. Dura 2 min."}
MultiLanguageSpellData['mx'][165751] = {name = "Ola de choque", additional_info = "Hechizo de 2 seg 20 seg de reutilización\n[q]Envía una ola de fuerza frente al guerrero, lo que inflige daño y aturde a los objetivos enemigos en un radio de 10 m en un cono frontal durante 4 s."}
