MultiLanguageSpellData['mx'][165766] = {name = "Dispersión", additional_info = "Instante\n[q]Te conviertes en energía de las Sombras pura y reduces todo el daño recibido un 75%. No puedes atacar ni lanzar hechizos, pero regeneras un 90% de maná cada segundo durante 6 s. Dispersión se puede lanzar mientras estás aturdido, asustado o silenciado, quita todos los efectos de frenado y de reducción de movimiento al lanzarlo y te hace inmune a ellos mientras dura."}
MultiLanguageSpellData['mx'][165767] = {name = "Forma de las Sombras", additional_info = "40% del maná base\nInstante\n[q]Adoptas la forma de las Sombras, lo que aumenta el daño de las Sombras que infliges un 20% y reduce el daño cuerpo a cuerpo recibido un 20%. Forma de las Sombras dura hasta que se cancela."}
