MultiLanguageSpellData['mx'][165773] = {name = "Escudo de tierra", additional_info = "Alcance de 40 m\nInstante\n[q]Protege al objetivo con un escudo de tierra que hace que los ataques cuerpo a cuerpo sanen al objetivo protegido. Este efecto solo ocurre una vez cada pocos segundos. 10 cargas. Dura 10 min.\n(3.5s de reutilización)"}
MultiLanguageSpellData['mx'][165774] = {name = "Tótem Nexo Terrestre", additional_info = "30 maná\nInstante\nHerramientas: Tótem de tierra\n[q]Invoca un Tótem Nexo Terrestre que reduce periódicamente la velocidad de movimiento de los enemigos cercanos a un 50% de lo normal. Dura 45 s."}
