MultiLanguageSpellData['mx'][168287] = {name = "Avatar de Terokk: muerte de Kargath", additional_info = nil}
MultiLanguageSpellData['mx'][168289] = {name = "Hechizo de modelo de arqueología", additional_info = "Hechizo de 2 seg\n[q]Aunque los mántides usan lanaviento y seda imperial, su material preferido es una especie de \"tejido\" que se fabrica con las alas de varias criaturas insectoides, incluidos ellos mismos. Este estandarte sirve de ejemplo."}
MultiLanguageSpellData['mx'][168290] = {name = "Hacha Lobo Gélido con colmillos marcados", additional_info = "Hechizo de 2 seg 5\n[q]Para ganar por completo la aceptación dentro del clan Lobo Gélido, cada miembro debe emprender la misión personal de hacerse amigo y crear un vínculo con un lobo gélido salvaje. No todos los miembros del clan superan esta prueba, pero aquellos que lo consiguen ganan un compañero de por vida."}
MultiLanguageSpellData['mx'][168291] = {name = "Talla adornada de linaje Lobo Gélido", additional_info = "Hechizo de 2 seg 5\n[q]Como parte del rito de iniciación a la adultez, los orcos Lobo Gélido deben matar a un jabagélido y tallar su genealogía de manera tan extensa como sea posible en el colmillo más grande de la criatura. La historia y tradición familiares son de gran importancia para el clan Lobo Gélido, por lo que cada temporada los jabagélidos más grandes son cazados en pos de la preservación del linaje del clan."}
MultiLanguageSpellData['mx'][168292] = {name = "Zuecos de Nieve de piel de lobo", additional_info = "Hechizo de 2 seg 5\n[q]Dada la pobre nutrición vegetal del desierto de Ventogélido, el sustento de los Lobo Gélido depende de sus cazadores. Estos zuecos de Nieve, constituidos por huesos y piel de lobo, ayudan a evitar que los rastreadores se hundan en los amontonamientos profundos mientras persiguen a su presa."}
MultiLanguageSpellData['mx'][168293] = {name = "Tambores Anunciaguerras", additional_info = "Hechizo de 2 seg 5\n[q]Valiéndose del terror y la conmoción para subyugar a sus enemigos, los Grito de Guerra se ganaron ese nombre por sus aterradores gritos de guerra y estruendosas marchas con tambores. Estos macabros tambores están constituidos por piel de talbuk firmemente estirada sobre lo que parecen ser cráneos de ogro, a modo de celebración de su liberación del imperio ogro."}
MultiLanguageSpellData['mx'][168294] = {name = "Churinga gritadora", additional_info = "Hechizo de 2 seg 5\n[q]Una churinga es una pieza de madera rígida del tamaño de un brazo que está atada a una larga cuerda y es girada sobre la cabeza de quien la maneja para generar un gran zumbido capaz de viajar largas distancias. Este ejemplo fue tomado por los Grito de Guerra para emitir un silbido agudo en vez del tarareo grave que emplean la mayoría de los otros clanes."}
MultiLanguageSpellData['mx'][168295] = {name = "Pica ceremonial Grito de Guerra", additional_info = "Hechizo de 2 seg 5\n[q]Los jinetes del clan Grito de Guerra son nómadas. En los campamentos, la tienda de la familia se marca con un gran pincho largo plantado en el suelo, y a veces adornado con las calaveras de los enemigos derrotados. Este ejemplo tiene más de cien años y está marcado con el nombre de muchas batallas cruciales."}
MultiLanguageSpellData['mx'][168296] = {name = "Martillo de Trabajador de metal", additional_info = "Hechizo de 2 seg 5\n[q]A pesar de tener muchos rasguños y mellas, se puede apreciar la iconografía del clan Roca Negra grabada en este martillo, alguna vez imponente. Los Roca Negra, primer clan de orcos en dominar el arte de trabajar el metal del mismo nombre, prefieren empuñar armas desafiladas durante una batalla para honrar a sus ancestros."}
MultiLanguageSpellData['mx'][168297] = {name = "Fuelle elemental", additional_info = "Hechizo de 2 seg 5\n[q]El clan Roca Negra originalmente usaba los infiernos alimentados por elementales y de origen natural que eran parte del antiguo Draenor, para moldear y endurecer la mena del mismo nombre. Un chamán podía usar estos fuelles para canalizar el poder de un espíritu de fuego directo a un Alto horno, permitiendo a los Roca Negra montar fraguas en cualquier lugar."}
MultiLanguageSpellData['mx'][168298] = {name = "Navaja de Roca Negra", additional_info = "Hechizo de 2 seg 5\n[q]Los orcos machos del clan Roca Negra no cortan su cabello hasta que se hacen adultos. Es entonces cuando se afeitan la cabeza y se determina su papel en esta sociedad extremadamente rígida. Esta navaja está forjada con roca negra y decorada con joyas; seguramente la usó una familia importante en iniciaciones de muchas generaciones."}
MultiLanguageSpellData['mx'][168299] = {name = "Hacha cortante pesada", additional_info = "Hechizo de 2 seg 5\n[q]Tomando su nombre literalmente, los guerreros del clan Mano Destrozada ceremonialmente destrozan su propia mano antes de cortarla. El muñón es cauterizado y remplazado con una de muchas variedad de armas. Esta hoja, que se parece a una simple cuchilla de carnicero, está cargada con peso para ayudar a hacer un solo corte en la muñeca."}
MultiLanguageSpellData['mx'][168300] = {name = "Daga enganchada", additional_info = "Hechizo de 2 seg 5\n[q]Los Mano Destrozada celebran las victorias de sus batallas mediante la automutilación. Sus guerreros más célebres están llenos de cicatrices y perforaciones, y con la edad se vuelve más y más difícil distinguir cuáles fueron infringidas por los enemigos y cuáles por el triunfante orco."}
MultiLanguageSpellData['mx'][168301] = {name = "Anzuelo con púas", additional_info = "Hechizo de 2 seg 5\n[q]Este nido de púas del tamaño de un brazo tiene poco en común con un anzuelo tradicional y más con una alabarda elaborada. Puedes imaginarte el tamaño del leviatán que podría morder este anzuelo, y no sorprende que la mayoría de los orcos prefieran cazar a sus presas en tierra."}
MultiLanguageSpellData['mx'][168302] = {name = "Ojo calcificado en un tarro", additional_info = "Hechizo de 2 seg 5\n[q]Este ojo bien conservado debió haber pertenecido a algún jefe del clan Foso Sangrante. Luego de ascender a gobernante del clan, cada jefe empieza una misión de visión chamánica en la que sacrifican su ojo para presenciar su propia muerte. Solo puedes imaginar el terrible destino que presenció este ojo nublado ."}
MultiLanguageSpellData['mx'][168303] = {name = "Agujas para tatuajes ceremoniales", additional_info = "Hechizo de 2 seg 5\n[q]Estas agujas de hueso son tomadas de los cadáveres de enemigos vencidos y cuidadosamente afiladas. Los místicos de Sombraluna a menudo inscriben runas secretas en su propia piel para hablar con mayor claridad con sus ancestros y los espíritus elementales."}
MultiLanguageSpellData['mx'][168304] = {name = "Ídolo de marfil rajado", additional_info = "Hechizo de 2 seg 5\n[q]Como ejemplo de la veneración al Vacío alguna vez practicada, pero que actualmente está prohibida por los ancianos del clan Sombraluna, está este ídolo tan oscuro como el manto nocturno. Cincelado frenéticamente y con poco esmero en el colmillo de lo que debió ser un elekk colosal, este ídolo fue teñido y está adornado con patrones ondulados y dentados."}
MultiLanguageSpellData['mx'][168305] = {name = "Talismán ancestral", additional_info = "Hechizo de 2 seg 5\n[q]Para los chamanes Sombraluna es esencial consultar a los espíritus de generaciones previas cuando se debe tomar una decisión importante. Los talismanes y otras reliquias que fueran importantes para un ancestro durante su vida, proporcionan un conducto espiritual más claro para que los chamanes hablen con ellos en el más allá."}
MultiLanguageSpellData['mx'][168306] = {name = "Frasco de grasa luminosa", additional_info = "Hechizo de 2 seg 5\n[q]La sustancia pegajosa, apestosa y muy inflamable en este contenedor se aplica normalmente a las espadas y hachas del clan Filo Ardiente antes de cada batalla. Aunque algunos guerreros optan por prender fuego a sus armas antes de combatir, muchos dejan que el contacto inevitable de los filos y las armas enciendan la grasa luminosa para intimidar con sorpresa."}
MultiLanguageSpellData['mx'][168307] = {name = "Collar de dientes de gronn", additional_info = "Hechizo de 2 seg 5\n[q]Los Señor del Trueno son los mejores de todo Draenor en la caza mayor. Por siglos, han utilizado bestias para montar y han coordinado ataques para matar gronn por diversión. El clan obtiene su nombre de un viejo jefe que mató con una sola mano a un poderoso gronn en el pináculo de Pico del Trueno."}
MultiLanguageSpellData['mx'][168308] = {name = "Profecía del Juicio Final", additional_info = "Hechizo de 2 seg 5\n[q]Esta tableta habla de \"el tiempo final\". Por lo que se puede descifrar, los garabatos de todos estos autores hablan de al menos siete versiones distintas, y a veces contradictorias, del día del juicio de todos los habitantes de Draenor. Lo que es algo siniestro es que se distingue muy claramente la iconografía de un martillo en llamas, ¿será este el origen ancestral del clan del Martillo Crepuscular?"}
MultiLanguageSpellData['mx'][168309] = {name = "Piedra de sucesión Quebrantarrocas", additional_info = "Hechizo de 2 seg 5\n[q]Los jefes comandan con puño de hierro a las bandas de ogros pequeñas, y nunca les faltan contendientes. El clan Quebrantarrocas tiene un número notoriamente alto en cambio de liderazgo. A juzgar por las capas de sangre, esta piedra parece haber sido pieza instrumental para derrocar a múltiples jefes Quebrantarrocas."}
MultiLanguageSpellData['mx'][168310] = {name = "Esposas de piedra", additional_info = "Hechizo de 2 seg 5\n[q]En vez de utilizar grilletes y cerraduras, los ogros atan a sus esclavos con pequeños círculos de piedra íntegra. Tras siglos de manipular los elementos de la tierra, ellos simplemente encogen las esposas alrededor de los talones, muñecas o cuellos de los esclavos."}
MultiLanguageSpellData['mx'][168311] = {name = "Figurilla de ogro", additional_info = "Hechizo de 2 seg 5\n[q]Esta estatua expresa a través de la escultura lo que para la mayoría de los ogros sería difícil comunicar con palabras, y resume el más importante atributo físico de los ogros: el tamaño. El uñagrieta que el ogro sostiene por encima de su cabeza demuestra fuerza, mientras que su robusta cintura es un símbolo de gran riqueza."}
MultiLanguageSpellData['mx'][168312] = {name = "Pictograma tallado", additional_info = "Hechizo de 2 seg 5\n[q]Aunque la tradición escrita suele usarse como un instrumento de los escalafones superiores de la sociedad imperial de ogros, ocasionalmente algún ogro común intenta hacer de una historia algo inmortal. Parece que este pictograma cuenta la historia de una experiencia culinaria especialmente inquietante."}
MultiLanguageSpellData['mx'][168313] = {name = "Escudo de Gladiador.", additional_info = "Hechizo de 2 seg 5\n[q]Los desacuerdos entre ogros usualmente terminan en violencia. Durante las primeras décadas de la Era del Orden, un astuto jefe decretó que las disputas de su clan se resolverían mediante combates cuerpo a cuerpo entre esclavos representantes. La tasa de mortalidad entre ogros fue en decremento, lo que condujo a una era dorada de expansión."}
MultiLanguageSpellData['mx'][168314] = {name = "Mortero y majadero", additional_info = "Hechizo de 2 seg 5\n[q]Ya que los ogros prefieren alardear sobre su físico, evitan las prendas que cubren demasiada piel. Para lucir más atemorizantes frente a sus enemigos, adornan sus cuerpos con pintura de guerra creada en estas molederas. Este equipo de mortero y majadero está manchado de amarillo, lo que indica que fue utilizado por el clan Puño de roca.\nSe liga al recogerlo\n[q2]Uso: Embala cuidadosamente el artefacto restaurado.\n[q]\"Los detalles del artefacto ya se han registrado en la pestaña Artefactos completados de tu diario de arqueología.\""}
MultiLanguageSpellData['mx'][168315] = {name = "Ojo de Har'gunn, el Ciego", additional_info = "Hechizo de 2 seg 5\n[q]A pesar de que la mayoría de los ogros nace con dos ojos, en cada generación un puñado de ellos nace con un solo ojo. Con excepción de unos pocos clanes, el resto cree que estos ogros están destinados para grandes cosas. Un desafortunado mago ogro de un ojo lo perdió en un duelo y lo remplazó con esta piedra del tamaño de un puño y, al hacerlo, descubrió que esta tenía propiedades mágicas."}
MultiLanguageSpellData['mx'][168316] = {name = "Dentaduras de piedra", additional_info = "Hechizo de 2 seg 5\n[q]Los ogros son directos en combate y comúnmente reciben una paliza tan dura como la que proporcionan, por lo que confían en su fuerza y aguante para alcanzar la victoria. Estas dentaduras serradas son prueba de que por lo menos a uno le tiraron todos los dientes y vivió para volver a pelear."}
MultiLanguageSpellData['mx'][168317] = {name = "Arnés de montar para rylak", additional_info = "Hechizo de 2 seg 5\n[q]Una vez a un ogro brillante se le ocurrió que montar un rylak haría que los viajes fueran más veloces que utilizar animales de carga o caminar. Confeccionado con poco esmero a partir de cuero grueso y utilizando un excesivo número de nudos, este asiento podría ser cómodamente utilizado por un ogro. Sin embargo, solo funcionaría para ensillar un rylak del tamaño de una montaña pequeña, lo que explica por qué nunca nadie ha visto volar a un ogro."}
MultiLanguageSpellData['mx'][168318] = {name = "Estela de decreto imperial", additional_info = "Hechizo de 2 seg 5\n[q]Unos fragmentos ensamblados de esta estela de piedra la ubican en Talador, siglos antes de que llegaran los draenei. Marca un decreto imperial de ogros de arrasar con muchos asentamientos de orcos, como represalia por varias bandas de rebeldes en contra de las caravanas de comercio de esclavos Gorian. Seguramente, las órdenes se llevaron a cabo porque las ciudades ya no existen, y esta piedra se erigió para honrar esa hazaña oscura."}
MultiLanguageSpellData['mx'][168319] = {name = "[q3]Anillo de dedo del pie de rey hechicero", additional_info = "Hechizo de 2 seg 10\n[q]Los ogros imperiales guardan con recelo los secretos de magia para mantener su posición entre la clase gobernante. Los más ricos se adornan con joyas mejoradas mágicamente y otros artefactos utilizables.\n[q3]Anillo de dedo del pie de rey hechicero\n[q7]Se liga a la tropa\nCuello\n+3 intelecto\n+4 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\n[q2]Aumenta tu índice de celeridad + 2 p.\nNecesitas ser de nivel 35"}
MultiLanguageSpellData['mx'][168320] = {name = "[q3]Mazo de guerra del Jefe de los Mazo de Guerra", additional_info = "Hechizo de 2 seg 10\n[q]La primera gran innovación tecnológica de la sociedad ogro fue el concepto de atar una roca al extremo de un palo largo para golpear a los enemigos, en vez de intentar golpearlos con una roca en las manos. La división resultante dentro de la sociedad ogro se resolvió sólo cuando el ya olvidado clan se dividió en los clanes Mazo de Guerra y Puño de Roca.\n[q3]Mazo de guerra del Jefe de los Mazo de Guerra\n[q7]Se liga a la tropa\nDos manos Maza\n10 - 14 p. de daño Velocidad 3.60\n(3.3 p. de daño por segundo)\n+5 fuerza\n+7 aguante\n[q2]Aumenta tu índice de golpe crítico + 5 p.\n[q2]Aumenta tu índice de celeridad + 3 p.\nDurabilidad 100 / 100\nNecesitas ser de nivel 35"}
MultiLanguageSpellData['mx'][168321] = {name = "Atrapasueños", additional_info = "Hechizo de 2 seg 5\n[q]Cuando Terokk volvió del exilio estaba roto y sin fuerzas. Se decía que su estado maldito barrió en arakkoa como un fuego incontrolado, lo que dio lugar a amuletos y curas. Los atrapasueños persisten como uno de los íconos de seguridad más populares, ya que los arakkoa creen que la maldición se enredará en el atrapasueños y desaparecerá con la luna."}
MultiLanguageSpellData['mx'][168322] = {name = "Urna funeraria", additional_info = "Hechizo de 2 seg 5\n[q]En la muerte los arakkoa buscan unirse al Dios del Sol Rukhmar en los cielos sobre Draenor, por lo que prefieren la cremación al entierro. Algunos esparcen sus cenizas por los cielos y otros las recolectan en urnas y criptas."}
MultiLanguageSpellData['mx'][168323] = {name = "Pergaminos de decreto", additional_info = "Hechizo de 2 seg 5\n[q]Estos escritos incompletos parecen indicar un decreto de un tipo de ley marcial y recordatorios acerca de estar atento ante señales de la maldición entre vecinos y amigos."}
MultiLanguageSpellData['mx'][168324] = {name = "Orbe solar", additional_info = "Hechizo de 2 seg 5\n[q]La reverencia a Rukhmar y al sol es central en la cultura de los Altos arakkoa. Cientos de orbes solares están dispersos en Trecho Celestial y emiten una luz eterna para que ningún arakkoa deba andar sin el calor del sol, aún en un día frío y nublado."}
MultiLanguageSpellData['mx'][168325] = {name = "Reloj de sol", additional_info = "Hechizo de 2 seg 5\n[q]Este instrumento grabado elegantemente, al posicionarlo correctamente actúa tanto como un reloj solar y como un calendario de estaciones arakkoa. La base de este instrumento está cubierta de invocaciones a eventos celestiales, de los cuales la mayoría también lleva advertencias. Lo que es interesante es que parece que este dispositivo predijo de manera críptica la llegada de los draenei un siglo antes de que sucediera."}
MultiLanguageSpellData['mx'][168326] = {name = "Máscara de Sacerdote de la Garra", additional_info = "Hechizo de 2 seg 5\n[q]Al creer que fueron abandonados por el sol, los arakkoa maldecidos prefieren esconderse en los bosques o detrás de marquesinas durante el día. Los Sacerdotes de la Garra llevan esto un poco más allá y nunca se dejan ver durante esas horas; llevan máscaras rituales que actúan como un foco para sus conversaciones con Anzu."}
MultiLanguageSpellData['mx'][168327] = {name = "Atrapasueños marginado", additional_info = "Hechizo de 2 seg 5\n[q]Los arakkoa marginados han reutilizado el atrapasueños, no para alejar a la Maldición de Sethe, sino para secuestrar y cosechar pequeñas cantidades de esencias de sus dioses perdidos. Los rumores insisten acerca de una masa creciente de energía arremolinada, enterrada debajo de Skettis, susurrando promesas de poder a quien quiera escuchar..."}
MultiLanguageSpellData['mx'][168328] = {name = "Cristal de ápices", additional_info = "Hechizo de 2 seg 5\n[q]Hay fragmentos y susurros de la civilización Apexis esparcidos por las ruinas más antiguas de Draenor. Ellos obtuvieron un gran poder durante la Era del Orden y de pronto desaparecieron. La llegada de la Horda de Hierro ha dado lugar a una intensificación secreta pero urgente respecto de la recuperación de los artefactos Apexis de las manos de los Partidarios."}
MultiLanguageSpellData['mx'][168329] = {name = "Jeroglífico Apexis", additional_info = "Hechizo de 2 seg 5\n[q]Esta tablilla de piedra, quebradiza y muy antigua, contiene inscripciones que describen en líneas generales un motor de un poder increíble... que emplea el poder del sol."}
MultiLanguageSpellData['mx'][168330] = {name = "Pergamino Apexis", additional_info = "Hechizo de 2 seg 5\n[q]Este cajón de pergaminos maltrecho se ha oxidado y aún con mucha atención el pergamino en su interior apenas puede leerse. Parecen ser planos y medidas para un \"Templo en el Cielo\" glorioso, escritos por una mano ancestral. No está claro si esta estructura espléndida finalmente se construyó."}
MultiLanguageSpellData['mx'][168331] = {name = "[q3]Partepicos de Terokk", additional_info = "Hechizo de 2 seg 10\n[q]Evitando las armas tradicionales arakkoa, Terokk llevó esta cayada como símbolo de su caída de rey a hereje marginado. Por siglos se ha dicho que más que emplear el castigo corta-alas tradicional, Terokk simplemente destrozó los picos de quienes osaron enfrentarlo.\n[q3]Partepicos de Terokk\n[q7]Se liga a la tropa\nUna mano Maza\n5 - 7 p. de daño Velocidad 2.60\n(2.3 p. de daño por segundo)\n+2 [Agilidad o Fuerza]+3 aguante\n[q2]Aumenta tu índice de golpe crítico + 2 p.\n[q2]Aumenta tu índice de maestría + 2 p.\nDurabilidad 90 / 90\nNecesitas ser de nivel 35"}
