MultiLanguageSpellData['mx'][171206] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir las Minas Muro de Escarcha.\n\n Level 1\nPermite a los jugadores extraer piedra draénica de nodos minerales en Draenor. La piedra draénica puede convertirse en pedidos para minerales de Draenor.\n\n Level 2\nPermite que los seguidores con la característica de minería trabajen aquí, lo que otorga una bonificación única. Además, abre un pozo de mina nuevo que permite el acceso a nodos minerales extra y hasta 14 pedidos de una vez.\n\n Level 3\nUn último pozo de mina permite el acceso a nodos minerales ricos. También, los guardias de la fortaleza patrullarán tu mina, manteniendo alejados a los goren hostiles. Además, permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][171208] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tus Minas Muro de Escarcha al nivel 2.\n\n Level 1\nPermite a los jugadores extraer piedra draénica de nodos minerales en Draenor. La piedra draénica puede convertirse en pedidos para minerales de Draenor.\n\n Level 2\nPermite que los seguidores con la característica de minería trabajen aquí, lo que otorga una bonificación única. Además, abre un pozo de mina nuevo que permite el acceso a nodos minerales extra y hasta 14 pedidos de una vez.\n\n Level 3\nUn último pozo de mina permite el acceso a nodos minerales ricos. También, los guardias de la fortaleza patrullarán tu mina, manteniendo alejados a los goren hostiles. Además, permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][171209] = {name = "Cargar cajón", additional_info = nil}
MultiLanguageSpellData['mx'][171210] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tus Minas Muro de Escarcha al nivel 2.\n\n Level 1\nPermite a los jugadores extraer piedra draénica de nodos minerales en Draenor. La piedra draénica puede convertirse en pedidos para minerales de Draenor.\n\n Level 2\nPermite que los seguidores con la característica de minería trabajen aquí, lo que otorga una bonificación única. Además, abre un pozo de mina nuevo que permite el acceso a nodos minerales extra y hasta 14 pedidos de una vez.\n\n Level 3\nUn último pozo de mina permite el acceso a nodos minerales ricos. También, los guardias de la fortaleza patrullarán tu mina, manteniendo alejados a los goren hostiles. Además, permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][171211] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tus Minas Muro de Escarcha al nivel 3.\n\n Level 1\nPermite a los jugadores extraer piedra draénica de nodos minerales en Draenor. La piedra draénica puede convertirse en pedidos para minerales de Draenor.\n\n Level 2\nPermite que los seguidores con la característica de minería trabajen aquí, lo que otorga una bonificación única. Además, abre un pozo de mina nuevo que permite el acceso a nodos minerales extra y hasta 14 pedidos de una vez.\n\n Level 3\nUn último pozo de mina permite el acceso a nodos minerales ricos. También, los guardias de la fortaleza patrullarán tu mina, manteniendo alejados a los goren hostiles. Además, permite hasta 21 pedidos a la vez."}
MultiLanguageSpellData['mx'][171212] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un Molino de guerra en tu fortaleza.\n\n Level 1\nDuplica la posibilidad de que tus recompensas de misiones obtengan una mejora de bonificación poco común o épica y aumenta la potencia de la mejora. Permite recolectar restos de armadura de los clanes orcos de Draenor para transfigurar la armadura.\n\n Level 2\nAbre pedidos de armas y armadura de seguidor a cambio de recursos de la fortaleza. Además, desbloquea nuevas armaduras de transfiguración.\n\n Level 3\nOtorga 1 de tus 3 sellos del destino inevitable (lanzamiento de dados bonus de banda) sin costo, cada semana."}
MultiLanguageSpellData['mx'][171213] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Molino de guerra al nivel 2.\n\n Level 1\nDuplica la posibilidad de que tus recompensas de misiones obtengan una mejora de bonificación poco común o épica y aumenta la potencia de la mejora. Permite recolectar restos de armadura de los clanes orcos de Draenor para transfigurar la armadura.\n\n Level 2\nAbre pedidos de armas y armadura de seguidor a cambio de recursos de la fortaleza. Además, desbloquea nuevas armaduras de transfiguración.\n\n Level 3\nOtorga 1 de tus 3 sellos del destino inevitable (lanzamiento de dados bonus de banda) sin costo, cada semana."}
MultiLanguageSpellData['mx'][171214] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Molino de guerra al nivel 3.\n\n Level 1\nDuplica la posibilidad de que tus recompensas de misiones obtengan una mejora de bonificación poco común o épica y aumenta la potencia de la mejora. Permite recolectar restos de armadura de los clanes orcos de Draenor para transfigurar la armadura.\n\n Level 2\nAbre pedidos de armas y armadura de seguidor a cambio de recursos de la fortaleza. Además, desbloquea nuevas armaduras de transfiguración.\n\n Level 3\nOtorga 1 de tus 3 sellos del destino inevitable (lanzamiento de dados bonus de banda) sin costo, cada semana."}
MultiLanguageSpellData['mx'][171215] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un Recinto de los espíritus en tu fortaleza.\n\n Level 1\nPermite la recolección de piedras de camino ogras de los ogros de Draenor. Estas piedras de camino se usan para potenciar la puerta ogra que quieras en Draenor. A veces también activan runas de poder durante el combate.\n\n Level 2\nDesbloquea el acceso a una segunda puerta ogra por un total de 2.\n\n Level 3\nDesbloquea el acceso a una tercera puerta ogra por un total de 3."}
MultiLanguageSpellData['mx'][171216] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Recinto de los espíritus al nivel 2.\n\n Level 1\nPermite la recolección de piedras de camino ogras de los ogros de Draenor. Estas piedras de camino se usan para potenciar la puerta ogra que quieras en Draenor. A veces también activan runas de poder durante el combate.\n\n Level 2\nDesbloquea el acceso a una segunda puerta ogra por un total de 2.\n\n Level 3\nDesbloquea el acceso a una tercera puerta ogra por un total de 3."}
MultiLanguageSpellData['mx'][171217] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para mejorar tu Recinto de los espíritus al nivel 3.\n\n Level 1\nPermite la recolección de piedras de camino ogras de los ogros de Draenor. Estas piedras de camino se usan para potenciar la puerta ogra que quieras en Draenor. A veces también activan runas de poder durante el combate.\n\n Level 2\nDesbloquea el acceso a una segunda puerta ogra por un total de 2.\n\n Level 3\nDesbloquea el acceso a una tercera puerta ogra por un total de 3."}
MultiLanguageSpellData['mx'][171218] = {name = "Aprendiendo", additional_info = "Hechizo de 3 seg\n[q]Proporciona los planos necesarios para construir un edificio de meca-taller gnómico en tu fortaleza.\n\n Level 1\nDesbloquea un ingeniero personal que crea un invento poderoso cada día. ¡Un trabajo excepcional!\n\n Level 2\nTu ingeniero gana acceso a cinco instrumentos nuevos e increíbles.\n\n Level 3\nPermite la creación de un vehículo de asedio una vez por día. ¡Condúcelo a la victoria en Draenor!"}
