MultiLanguageSpellData['mx'][171221] = {name = "Seguidora: Defensora Illona", additional_info = "Instante\n[q]Illona siempre soñó que algún día se uniría a la antigua orden Auchenai. Cuando el exarca Maladaar lanzó un llamado de ayuda a todos los draenei disponibles y capaces, Illona tomó la armadura de su abuelo y salió en busca de su destino."}
