MultiLanguageSpellData['mx'][171244] = {name = "Seguidor: Ahm", additional_info = "Instante\n[q]Ahm fue capturado por el maestro del acero Bralok cuando el cruel orco atacó su hogar. El orco ordenó golpear y privar de comida a Ahm, pero este no cedió. Tras su muerte, continúa preservando y buscando la venganza en contra de la Horda de Hierro por sus farsas."}
