MultiLanguageSpellData['mx'][171612] = {name = "Alma reptadora", additional_info = "Alcance de 100 m\nInstante\n[q]El taumaturgo extrae la fuerza de vida de las criaturas de la cueva. Cualquiera de estos espíritus que alcance al taumaturgo lo sana un 2% de su salud máxima. Cualquier jugador que interrumpa a estos espíritus sufre daño de las Sombras."}
MultiLanguageSpellData['mx'][171613] = {name = "Tótem del infierno", additional_info = "Alcance de 100 m\nInstante\n[q]Invoca un tótem del infierno ardiente."}
MultiLanguageSpellData['mx'][171614] = {name = "Inferno", additional_info = "Hechizo de 5 seg\n[q]Inflige 87 p. de daño de Fuego a todos los enemigos que se encuentren en un radio de 45 m."}
MultiLanguageSpellData['mx'][171615] = {name = "Fuegos artificiales encantadores", additional_info = "Instante\n[q]Desata el poder del amor."}
MultiLanguageSpellData['mx'][171616] = {name = "Trotacantilados pelajemarchito", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Trotacantilados pelajemarchito.\n[q]\"Muescas diminutas cubren las pezuñas de esta variación de uñagrieta, lo que le permite escalar con firmeza regiones montañosas en busca de comida.\"\nVendedor:\nComerciante Araanda\nZona:\nCaída de la Luna\nCosto:\n20000\n\nVendedor:\nComerciante Darakk\nZona:\nMuro de Escarcha\nCosto:\n20000"}
MultiLanguageSpellData['mx'][171617] = {name = "Cascohielo entrenado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Cascohielo entrenado.\n[q]\"No fue hasta que conseguiste esta montura que entendiste la magnitud de las pruebas a las que te pondría Draenor. ¡El pelo de uñagrieta se pega a todo!\"\nFuente:\nEstablos de la fortaleza"}
MultiLanguageSpellData['mx'][171618] = {name = "Piel de cuero anciano", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Piel de cuero anciano."}
MultiLanguageSpellData['mx'][171619] = {name = "Cascohielo de la tundra", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Cascohielo de la tundra.\n[q]\"Una capa traslúcida de cabello cubre el pellejo curtido de esta raza, lo que actúa como un aislamiento perfecto para ambientes fríos.\"\nBotín:\nVenganza, Garramuerte, Puño de terror, Rodador maldito\nZona:\nJungla Tanaan"}
MultiLanguageSpellData['mx'][171620] = {name = "Toro Pezuña de Sangre", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Toro Pezuña de Sangre.\n[q]\"Desde hace tiempo los miembros del clan Grito de Guerra cazan a estas uñagrietas para usar su piel de tonos carmesí en los estandartes de batalla.\"\nBotín:\nNakk el Tronador\nUbicación:\nNagrand"}
MultiLanguageSpellData['mx'][171621] = {name = "Destructor Patahierro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Destructor patahierro.\n[q]\"Se dice que Puño Negro diseñó personalmente los armamentos ígneos usados en las monturas de batalla de uñagrieta de la Horda de Hierro.\"\nBotín:\nPuño Negro\nUbicación:\nFundición de Roca Negra (Mítico)"}
MultiLanguageSpellData['mx'][171622] = {name = "Trotacampos moteado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Trotacampos moteado.\n[q]\"La trompa larga del elekk le permite olfatear fuentes de comida, evadir el peligro y robar bocadillos de tu bolsa cuando no estás mirando.\"\nBotín:\nLuk'hok\nZona:\nNagrand"}
MultiLanguageSpellData['mx'][171623] = {name = "Trotacampos entrenado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Trotacampos entrenado.\n[q]\"Los draenei perfeccionaron la cría de elekk hace años; adornaban a las criaturas con cristales imbuidos de luz para hacerlos más dóciles.\"\nMisión:\nEstablos de la fortaleza"}
MultiLanguageSpellData['mx'][171624] = {name = "Dentoperla Pielsombra", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Dentoperla Pielsombra.\n[q]\"Algunas leyendas dicen que los draenei se hicieron amigos de los elekk por primera vez cuando una de las bestias salvó a un explorador herido de una jauría de vainitas despiadadas.\"\nBotín:\ntesoro olvidado del invasor"}
MultiLanguageSpellData['mx'][171625] = {name = "Rocapiel polvoriento", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Rocapiel polvoriento.\n[q]\"Desde que adquiriste esta montura, te persiguen sueños de fiebre extraños de elekk que desfilan con bombos, platillos y toda la fanfarria.\"\nVendedor:\nVindicador Nuurem\nConsejo de Exarcas - Exaltado\nUbicación:\nEscudo de Tormenta\nCosto:\n5000\n+ 5000"}
MultiLanguageSpellData['mx'][171626] = {name = "Colmihierro acorazado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Colmihierro acorazado.\n[q]\"Se dice que el elekk no olvida. Con razón detestan a la Horda de Hierro, después de cómo los torturaban los orcos.\"\nVendedor:\n\nDefensa Sha'tari - Exaltado\nUbicación:\nPuesto de venta de la fortaleza\nCosto:\n5000\n+ 5000"}
MultiLanguageSpellData['mx'][171627] = {name = "Jabaguerrero de acero negro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Jabaguerrero de acero negro.\n[q]\"Se rehúsa a correr a menos que su cabeza esté cubierta de metal pesado y con pinchos. Puro ego.\"\nLogro:\nhermandad Gloria del asaltante de Draenor"}
MultiLanguageSpellData['mx'][171628] = {name = "Jabaguerrero Rocamuela", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Jabaguerrero rocamuela.\n[q]\"No es el casco de metal lo que atrae a sus parejas; es esa divina cresta mohicana.\"\nVendedor:\nComerciante Araanda\nZona:\nCaída de la Luna\nCosto:\n10000\n\nVendedor:\nComerciante Darakk\nZona:\nMuro de Escarcha\nCosto:\n10000"}
MultiLanguageSpellData['mx'][171629] = {name = "Jabaescarcha acorazado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Jabaescarcha acorazado.\n[q]\"Tiene una dieta casi por completo de frutos del bosque. Aunque también le resultan muy apetitosos los seres fuera de este mundo.\"\nLogro:\nCría de animales avanzada"}
MultiLanguageSpellData['mx'][171630] = {name = "Picovaja acorazado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Picovaja acorazado.\n[q]\"Nunca... jamás... NUNCA... dejes que te sienta olor a panceta.\"\nBotín:\nVenganza, Garramuerte, Puño de terror, Rodador maldito\nZona:\nJungla Tanaan"}
MultiLanguageSpellData['mx'][171631] = {name = "Achievement Credit", additional_info = "Instante\n[q]Permite mostrar los estandartes de tu hermandad en la fortaleza."}
MultiLanguageSpellData['mx'][171632] = {name = "Jabaguerrero de las llanuras congeladas", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Jabaguerrero de las llanuras congeladas.\n[q]\"Si no tuviera ese genial anillo de colmillo, se sentiría tan tonto vestido así...\"\nLogro:\nGloria del héroe de Draenor"}
MultiLanguageSpellData['mx'][171633] = {name = "Dentosangre salvaje", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Dentosangre salvaje.\n[q]\"Si quieres un viaje tranquilo, ve a buscar un \"animalito para domesticar\" o algo.\"\nVendedor:\nZ'tenga el Caminante\nZona:\nJungla Tanaan\nLos Acechadores de sable - Honorable\nCosto:\n1000"}
MultiLanguageSpellData['mx'][171634] = {name = "Picovaja domesticado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Picovaja domesticado.\n[q]\"Domesticado no necesariamente significa \"amigable\". Trae algunos bocadillos.\"\nVendedor:\nGazrix Engranaje Seguro / Mimi Contertulio\nSociedad de \"Preservación\" de Bonvapor - Exaltado\nUbicación:\nEscudo de Tormenta / Lanza de Guerra\nCosto:\n5000\n+ 5000"}
MultiLanguageSpellData['mx'][171635] = {name = "Morrofrío gigante", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Morrofrío gigante.\n[q]\"No solo tiene el hocico frío, sino también húmedo. No es la manera más linda de despertar.\"\nBotín:\ntesoro olvidado del invasor"}
MultiLanguageSpellData['mx'][171636] = {name = "Gran Colmigris", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Gran colmigris.\n[q]\"Cambia los colmillos una vez al año. Es muy tímido hasta que le vuelven a crecer.\"\nBotín:\nGorok\nZona:\nCresta Pirofrío"}
MultiLanguageSpellData['mx'][171637] = {name = "Rocamuela entrenado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Rocamuela entrenado.\n[q]\"Altamente entrenado para bufar, trotar y pisotear las caras de los enemigos.\"\nMisión:\nEstablos de la fortaleza"}
MultiLanguageSpellData['mx'][171638] = {name = "Revolcarríos entrenado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Revolcarríos entrenado.\n[q]\"Los revolcarríos son unas de las bestias más fuertes de Draenor, lo que da como resultado su aguante superior y colores distintivos.\"\nMisión:\nEstablos de la fortaleza"}
