MultiLanguageSpellData['mx'][171824] = {name = "Bestia de río zafiro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Bestia de río zafiro.\n[q]\"El color de este animal imita el azul claro de las aguas poco profundas de Draenor, lo que lo hace casi invisible a los depredadores acuáticos.\"\nBotín:\nCienopiel\nZona:\nTalador"}
MultiLanguageSpellData['mx'][171825] = {name = "Revolcarríos Pellejomusgo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Revolcarríos pellejomusgo.\n[q]\"Agresivo y territorial, el pellejomusgo se esconde entre la maleza de la ribera y le tiene emboscadas a transeúntes distraídos.\"\nVendedor:\nBuscalba Krek / Buscalba Alkset\nUbicación:\nEscudo de Tormenta / Lanza de Guerra\nCosto:\n50,000\n+ 5000"}
MultiLanguageSpellData['mx'][171826] = {name = "Bestia de río Lomofango", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Bestia de río lomofango.\n[q]\"Una red especial que crece en las plantas de los pies del lomofango les da tracción extra en el lodo y el terreno resbaladizo.\"\nMisión de la fortaleza:\nEs un barco, es un avión, es... solo una bestia del río."}
MultiLanguageSpellData['mx'][171827] = {name = "Infernal fuego infernal", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Infernal Fuego infernal.\n[q]\"Desde las entrañas del vacío se invoca una criatura de odio puro, decidida a incinerar cualquier alma que se atraviese en su camino.\"\nBotín:\nGul'dan (mítico)\nZona:\nLa Fortaleza Nocturna"}
MultiLanguageSpellData['mx'][171828] = {name = "Halconguja Solar", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Halconguja solar.\n[q]\"Mirar a los ojos de esta bestia mística es como observar el núcleo del sol. Sugerimos el uso de gafas mientras se lo monta.\"\nBotín:\nRukhmar"}
MultiLanguageSpellData['mx'][171829] = {name = "Destrero Sombramelena", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Destrero sombramelena.\n[q]\"Los poetas draenei han comparado los colores de este talbuk con las sombras que produce la luz de la luna en un bosque ceniciento.\"\nVendedor:\nParlacuervos Skeega / Sabio de las Sombras Brakoss\nDesterrados Arakkoa - Exaltado\nUbicación:\nEscudo de Tormenta / Lanza de Guerra\nCosto:\n5000\n+ 5000"}
MultiLanguageSpellData['mx'][171830] = {name = "Zancabrisa presto", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Zancabrisa presto.\n[q]\"Los draenei han confiado en esta montura, la más ligera de todos los talbuk, para que lleve a destino a los mensajeros y sus misivas a salvo.\"\nBotín:\nCorrecaminos\nZona:\nValle Sombraluna"}
MultiLanguageSpellData['mx'][171831] = {name = "Pielplateada entrenado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Pielplateada entrenado.\n[q]\"Preciada por su inteligencia, esta raza de talbuk puede entrenarse para ejecutar patadas defensivas y flagelos en batalla.\"\nUbicación:\nEstablos de la fortaleza"}
MultiLanguageSpellData['mx'][171832] = {name = "Semental Zancabrisa", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Semental Zancabrisa.\n[q]\"El color rojo de estos brisaligera refleja su temperamento: sanguíneos, feroces y corajudos.\"\nVendedor:\nDazzerian\nLanza de Vol'jin - Exaltado\nUbicación:\nLanza de Guerra\nCosto:\n5000\n+ 5000"}
MultiLanguageSpellData['mx'][171833] = {name = "Raspaespina pálido", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Raspaespina pálido.\n[q]\"Este talbuk vive de cardos y espinas, lo que hace que sea tan áspero adentro como afuera.\"\nVendedor:\nCrafticus Dominomente\nVanguardia de Wrynn - Exaltado\nUbicación:\nEscudo de Tormenta\nCosto:\n5000\n+ 5000"}
MultiLanguageSpellData['mx'][171834] = {name = "Carnero de guerra feroz", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Carnero de guerra feroz.\n[q]\"Solo te habrá aceptado realmente como su jinete después de que te haya dado un cabezazo bajo el cinturón.\"\nVendedor:\nNecroseñor Sipe\nZona:\nCiudad de Ventormenta\nCosto:\n1"}
MultiLanguageSpellData['mx'][171835] = {name = "Raptor de guerra feroz", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Raptor de guerra feroz.\n[q]\"Porque los dientes afilados y las garras no eran suficientes.\"\nVendedor:\nGuardia de la muerte Netharian\nZona:\nOrgrimmar\nCosto:\n1"}
MultiLanguageSpellData['mx'][171836] = {name = "Garn Fauceacero", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Garn fauceacero.\n[q]\"Una vez un entrenador intentó poner metal decorativo en la boca de su lobo fauceacero. Tuvo que esperar tres días para recuperarlo.\"\nBotín:\ntesoro olvidado del invasor"}
MultiLanguageSpellData['mx'][171837] = {name = "Colmitemible Grito de Guerra", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Colmitemible Grito de Guerra.\n[q]\"Tiene una voluntad de acero, pero es el más dulce si le das un hueso de uñagrieta para que mastique.\"\nBotín:\nVenganza, Garramuerte, Puño de terror, Rodador maldito\nZona:\nJungla Tanaan"}
MultiLanguageSpellData['mx'][171838] = {name = "Lobo gélido acorazado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Lobo gélido acorazado.\n[q]\"Está entrenado para sobrevivir el clima hostil de la Cresta Pirofrío, así que se acurruca como si su vida dependiera de ello.\"\nLogro:\nEl maestro de establo"}
MultiLanguageSpellData['mx'][171839] = {name = "Lobo de guerra Lomoférreo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Lobo de guerra Lomoférreo.\n[q]\"Tiene un pincho acorazado en su cola. Rasca su pancita... si te atreves.\"\nVendedor:\nKil'rip\nRiecráneos - Exaltado\nUbicación:\nPuesto de venta de la fortaleza de la Horda\nCosto:\n5000\n+ 5000"}
MultiLanguageSpellData['mx'][171840] = {name = "Infernal llamafría", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Infernal llamafría.\n[q]\"Las extrañas llamas heladas hacen que transpires y tirites al mismo tiempo.\"\nPuesto de venta"}
MultiLanguageSpellData['mx'][171841] = {name = "Gruñidor entrenado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Gruñidor entrenado.\n[q]\"Increíblemente tierno cuando es cachorro. Ahora un poquito menos.\"\nMisión:\nEstablos de la fortaleza"}
MultiLanguageSpellData['mx'][171842] = {name = "Lobo Gélido presto", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Lobo Gélido presto.\n[q]\"En las alturas frías de Pirofrío, los lobos gélidos cazan lo que consiguen. Los más rápidos comen mejor.\"\nVendedora:\nBeska Colmillorrojo\nOrcos Lobo Gélido - Exaltado\nUbicación:\nLanza de Guerra\nCosto:\n5000\n+ 5000"}
MultiLanguageSpellData['mx'][171843] = {name = "Lobo temible humeante", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Lobo temible humeante.\n[q]\"Se cree que vive mayormente al norte. Odia las bodas.\"\nBotín:\ntesoro olvidado del invasor"}
MultiLanguageSpellData['mx'][171844] = {name = "Lobo temible Polvomelena", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Lobo temible Polvomelena.\n[q]\"Precavido para los estándares de los lobos temibles, solo puedes convencer al polvomelena de que monte con algo que él considera especial.\"\nProfesión:\nPeletería"}
MultiLanguageSpellData['mx'][171845] = {name = "Rueda mortal del Señor de la Guerra", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Rueda mortal del Señor de la Guerra.\n[q]\"Comúnmente llamado \"goblin corta césped\", este monstruo gruñidor trata a los enemigos como si fueran pasto... listo para ser cortado.\"\nLogro:\nCategoría:\nProezas de fuerza"}
MultiLanguageSpellData['mx'][171846] = {name = "Motocuchilla del campeón", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Motocuchilla del campeón.\n[q]\"Forjada por humanos, gnomos y enanos, esta obra maestra acorazada está diseñada para convertir a un tauren en un filete listo para la cena con un movimiento rápido de los manillares.\"\nVendedor:\nPaulie\nZona:\nVentormenta, Casco Antiguo\nCosto:\n100000"}
MultiLanguageSpellData['mx'][171847] = {name = "Destrero Crin cinérea", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Destrero Crin cinérea.\n[q]\"Creado por el propio Ragnaros como regalo a la hija que nunca tuvo.\"\nRecluta a un amigo"}
MultiLanguageSpellData['mx'][171848] = {name = "Yeti de guerra del contendiente", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Yeti de guerra del contendiente.\n[q]\"Por suerte se mueven rápidamente y dejan la mayoría del olor atrás.\"\nLogro:\nSeñor de la Guerra de los desafíos: Plata"}
MultiLanguageSpellData['mx'][171849] = {name = "Gronnito Pellejosol", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Gronnito pellejosol.\n[q]\"Ama el sol, odia todo lo demás.\"\nBotín:\nLibrapuño\nZona:\nGorgrond"}
MultiLanguageSpellData['mx'][171850] = {name = "Merodeador Llothien", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Merodeador Llothien.\n[q]\"A pesar de su tamaño, estos estilizados zorros pueden acechar entre las hojas recién caídas sin hacer el más mínimo ruido.\"\nMisión:\nVolpin el Esquivo\nZona:\nSuramar"}
MultiLanguageSpellData['mx'][171851] = {name = "Aullanoches Garn", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Aullanoches Garn.\n[q]\"Los garn son los predadores más feroces en Draenor, y siempre cazan en manadas.\"\nBotín:\nNok-Karosh\nUbicación:\nCresta Pirofrío"}
