MultiLanguageSpellData['mx'][172539] = {name = "Vendaje antiséptico", additional_info = "Hechizo de 2 seg\nComponentes:\nPiel suntuosa (5)\n[q]Receta para 4. El rendimiento real varía según la habilidad en primeros auxilios.\nProfesión:\nSastrería de Draenor (1)\n\nVenda antiséptica\n[q2]Uso: Sana 2720 p. de daño durante 8 s.\nNecesitas ser de nivel 35\n[q]\"Las propiedades curativas del veneno de escorpión marino se pueden absorber por la piel, pero la aplicación es lenta.\""}
MultiLanguageSpellData['mx'][172540] = {name = "Tónico sanador", additional_info = "Hechizo de 2 seg\nComponentes:\nSegmento de escorpión marino (10)\n[q]Crea 4 tónicos sanadores. El resultado final puede variar según el nivel de habilidad.\nProfesión:\nAlquimia de Draenor (1)\n\n[q2]Uso: Restaura 3400 p. de salud. (5 Min Reutilización)\nNecesitas ser de nivel 35\n[q]\"Preparado correctamente, el veneno de escorpión marino puede restaurar la salud.\""}
MultiLanguageSpellData['mx'][172541] = {name = "Contravenenos de Aguasnegras", additional_info = "Hechizo de 2 seg\nComponentes:\nCarne de pez colátigo de Aguasnegras (10)\n[q]Crea 4 contravenenos de Aguasnegras. El resultado final puede variar según el nivel de habilidad.\nProfesión:\nAlquimia de Draenor (1)\n\n\n[q2]Uso: Cura envenenamientos de hasta nivel 49 y reduce la duración de nuevos envenenamientos un 50% durante 2 min. Solo funciona en Draenor. No se puede usar en estancias. (2 Min Reutilización)\nNecesitas ser de nivel 35"}
MultiLanguageSpellData['mx'][172542] = {name = "Aceite de amonita de fuego", additional_info = "Hechizo de 2 seg\nComponentes:\nTentáculo de amonita de fuego (10)\n[q]Crea 4 aceites de amonita de fuego. El resultado final puede variar según el nivel de habilidad.\nProfesión:\nAlquimia de Draenor (1)\n\n\n[q2]Uso: Cura enfermedades y reduce un 50% la duración de nuevas enfermedades durante 2 min. Solo funciona en Draenor. No se puede usar en estancias. No tiene efecto por encima de nivel 50. (2 Min Reutilización)\nNecesitas ser de nivel 35\n[q]\"Elimina la infección sin dañar al huésped.\""}
