MultiLanguageSpellData['mx'][178535] = {name = "Portal del brujo", additional_info = "Rango ilimitado\nInstante\n[q]Los brujos del Fuerte Escudo de Tormenta activaron los portales dentro de Ashran.\n\n Puedes verlos en tu mapa, al noroeste y al sureste de Ashran. Úsalos para viajar por Ashran más rápidamente.\n\n Entregarle 400 [fragmentos de artefacto] encontrados en Ashran a Marketa en la Avanzada Lanza de Guerra activará los portales."}
MultiLanguageSpellData['mx'][178536] = {name = "Jinetes de lobo", additional_info = "Rango ilimitado\nInstante\n[q]Los jinetes de lobo de la Avanzada Lanza de Guerra fueron enviados a patrullar la periferia de Ashran en búsqueda de cualquier signo de la Alianza.\n\n Armar a los jinetes de lobo requiere [fragmentos de artefacto] que se pueden encontrar en Ashran. Entrégaselos a Kalgan en la Avanzada Lanza de Guerra."}
MultiLanguageSpellData['mx'][178537] = {name = "Jinetes Caballeros", additional_info = "Rango ilimitado\nInstante\n[q]Los jinetes caballeros del Fuerte Escudo de Tormenta fueron enviados a patrullar la periferia de Ashran en búsqueda de cualquier signo de la Horda.\n\n Armar a los jinetes caballeros requiere [fragmentos de artefacto] que se pueden encontrar en Ashran. Entrégaselos a Valant Jurabrillo en el Fuerte Escudo de tormenta."}
MultiLanguageSpellData['mx'][178538] = {name = "Mago del Portal", additional_info = "Rango ilimitado\nInstante\n[q]Los magos del Fuerte Escudo de Tormenta activaron el portal del mago dentro de Ashran. Usa el portal para volver rápidamente al Fuerte Escudo de tormenta.\n\n Puedes encontrar el portal en tu mapa, al oeste cerca del Descanso del rey.\n\n Entregarle 400 [fragmentos de artefacto] encontrados en Ashran a Ecilam en el Fuerte Escudo de tormenta activará el portal."}
MultiLanguageSpellData['mx'][178539] = {name = "Mago del Portal", additional_info = "Rango ilimitado\nInstante\n[q]Los magos de la Avanzada Lanza de Guerra activaron el portal del mago dentro de Ashran. Usa el portal para volver rápidamente a la Avanzada Lanza de Guerra.\n\n Puedes encontrar el portal en tu mapa, al oeste cerca del Descanso del rey.\n\n Entregarle 400 [fragmentos de artefacto] encontrados en Ashran a Fura en la Avanzada Lanza de Guerra activará el portal."}
