MultiLanguageSpellData['mx'][181296] = {name = "Runas explosivas", additional_info = "Rango ilimitado\nHechizo de 2 seg\n[q]El taumaturgo crea Runas explosivas en el suelo. Si estas runas no se activan dentro de 15 s, explotan e infligen 13839 p. de daño de Fuego a todos los enemigos.\n\n Activar la runa provocará una explosión más pequeña que infligirá 10399 p. de daño de Fuego al jugador que la activó."}
MultiLanguageSpellData['mx'][181297] = {name = "Runas explosivas potenciadas", additional_info = "Rango ilimitado\nHechizo de 2 seg\n[q]Kormrok crea Runas explosivas potenciadas en el suelo. Si estas runas no se activan dentro de 15 s, explotan e infligen daño de Fuego a todos los enemigos.\n\n Cada vez que se activa una runa, se moverá en la dirección que esté mirando el jugador que la activó. Las Runas explosivas potenciadas solo se consumen por completo cuando son la última runa en juego o su movimiento provoca que se ubiquen sobre una runa existente."}
