MultiLanguageSpellData['mx'][181299] = {name = "Manos codiciosas", additional_info = "Hechizo de 2 seg\n[q]Kormrok invoca varias manos pétreas bajo los pies de sus enemigos, lo que inflige 2301 p. de daño físico a todos los enemigos en un radio de 4 m de la víctima. Estas manos mantienen a la víctima en el lugar hasta que mueren.\n\n Mientras permanece retenida, la víctima sufre 3098 p. de daño físico cada 3 s."}
MultiLanguageSpellData['mx'][181300] = {name = "Manos arrastradoras", additional_info = "Hechizo de 2 seg\n[q]Kormrok invoca varias manos pétreas bajo los pies de sus enemigos. Estas manos arrastran a sus víctimas al charco de energía vil más cercano.\n\n Mientras permanece retenida, la víctima sufre 35 p. de daño físico cada 3 s."}
