MultiLanguageSpellData['mx'][196468] = {name = "Capizana de Petrapiel", additional_info = "Hechizo de 1.5 seg\nComponentes:\nCuero de petrapiel curtido (30)\nCapizana de cuero de petrapiel\nObjeto de misión\nÚnico\n[q]\"Armadura para el cuello de la montura.\""}
MultiLanguageSpellData['mx'][196469] = {name = "Jirel de Petrapiel", additional_info = "Hechizo de 1.5 seg\nComponentes:\nCuero de petrapiel curtido (50)\nJirel de cuero de petrapiel\nObjeto de misión\nÚnico\n[q]\"Armadura para el cuerpo de la montura.\""}
MultiLanguageSpellData['mx'][196470] = {name = "Vasija vidrio violeta", additional_info = "Hechizo de 2 seg 5\n[q]La atracción de los Altonato por todas las cosas púrpura antecede a La Guerra de los Ancestros. Los boles de vidrio eran bastante comunes, y solían contener desde granos hasta lingotes de oro."}
MultiLanguageSpellData['mx'][196471] = {name = "Talismán de piedra ley inerte", additional_info = "Hechizo de 2 seg 5\n[q]Muchos Altonato supersticiosamente portaban trozos de piedra ley como amuletos de la suerte. Esos amuletos solían ser utilizados por granjeros, estudiantes de esfuerzo, o quienes se encontraban entre la gente común y la nobleza."}
MultiLanguageSpellData['mx'][196472] = {name = "Vial vino silencioso", additional_info = "Hechizo de 2 seg 5\n[q]Vino silencioso era un termino Altonato antiguo que simplemente significaba “veneno”. Irónicamente, luego de diez mil años en tierra, la sustancia suele perder su letalidad y se convierte en un suave tóxico."}
MultiLanguageSpellData['mx'][196473] = {name = "Tapiz Altonato pre-guerra", additional_info = "Hechizo de 2 seg 5\n[q]Los tapices fabricados antes de la era del pacto con los demonios de la Reina Azshara suelen mostrar un estilo de tejido único que no se ha visto desde entonces."}
MultiLanguageSpellData['mx'][196474] = {name = "Abridor de cartas del noble", additional_info = "Hechizo de 2 seg 5\n[q]Como siempre ocurre con los abrecartas, estas son herramientas inútiles, y se conservan como excusa para tener un arma letal cerca en situaciones en las que no sería socialmente correcto portar una daga."}
MultiLanguageSpellData['mx'][196475] = {name = "Tambor de iniciación", additional_info = "Hechizo de 2 seg 5\n[q]No todos los tauren de Altamontaña eran cazadores, pero los que sí, solían conmemorar su primera caza con un tambor ceremonial, cubierto con el pellejo de su cantera. La mayoría de los tambores de iniciación se hacen con piel de conejo o de zorro. Los cazadores solían conservarlos el resto de sus vidas."}
MultiLanguageSpellData['mx'][196476] = {name = "Gancho de pesca de hueso de alce", additional_info = "Hechizo de 2 seg 5\n[q]Los huesos de alce, en su tiempo, eran el material más común para carnadas de pesca: lo suficientemente duros como para tallarles puntas, pero lo suficientemente flexibles como para que no se rompan en la boca de un enorme salmón. Muchos pescadores tallaban elaborados diseños en sus “carnadas de la suerte”."}
MultiLanguageSpellData['mx'][196477] = {name = "Piropiedra alisada a mano", additional_info = "Hechizo de 2 seg 5\n[q]Era costumbre para una viuda, hijo, o nieto, conservar una piropiedra de la pira funeraria de un ser muy querido. Llevaban estas piedras en un bolsillo y los frotaban para pedir coraje, comodidad, o para recordar la perdida de un compañero caído."}
MultiLanguageSpellData['mx'][196478] = {name = "Rodillo de gemas drogbar", additional_info = "Hechizo de 2 seg 5\n[q]Si bien muchos drogbar apreciaban los duros bordes de las gemas puras, otros preferían las joyas más suaves y redondeadas. En lugar de usar herramientas de joyería normales, usaban un aparato de piedra operado a mano, que golpeaba las piedras por semanas. Eran generalmente operadas por sirvientes, esclavos, o jóvenes desobedientes."}
MultiLanguageSpellData['mx'][196479] = {name = "Arco de madera de piedra", additional_info = "Hechizo de 2 seg 5\n[q]Las extremidades del arco están talladas con madera tan dura como la piedra, lo que la hace casi imposible de empuñar. Los arqueólogos no concuerdan en si el arco siempre fue así de duro o si la madera simplemente se petrificó con los años. De cualquier modo, el tamaño y peso del arco sugiere que solo fue utilizado por los tauren más expertos."}
MultiLanguageSpellData['mx'][196480] = {name = "Taza del diablillo", additional_info = "Hechizo de 2 seg 5\n[q]Los diablillos también deben hidratarse, y muchos prefieren usar sus propias tazas. Algunos tienen la teoría de que una raza de diablillos antigua veneraba sus contenedores de líquidos como algo sagrado, y parte de ese ritual perseveró incluso luego de que fueron adoctrinados por la Legión Ardiente."}
MultiLanguageSpellData['mx'][196481] = {name = "Crónica del despellejado", additional_info = "Hechizo de 2 seg 5\n[q]Las diferentes razas de demonios exhiben diferentes comportamientos entre batalla y batalla. Los sucubus, por ejemplo, suelen llevar un registro detallado de sus actividades diarias. Estos suelen ser espeluznantes, casi grotescos, y los escriben principalmente en “papel” hecho con la piel de un enemigo o prisionero."}
MultiLanguageSpellData['mx'][196482] = {name = "Abisal deforme", additional_info = "Hechizo de 2 seg 5\n[q]El ritual para invocar a un abisal es complicado, y suele fallar. Cuando algo sale mal, una pequeña parte del demonio queda atrás, envuelto en una combinación de una latente rabia demoniaca y desesperación por su propia disfunción. Los campos de batalla más antiguos están llenos de tales piedras."}
MultiLanguageSpellData['mx'][196483] = {name = "Orbe de caos interior", additional_info = "Hechizo de 2 seg 5\n[q]El caos no le llega fácilmente a todos los demonios. Algunos luchan con el camino de La Legión Ardiente. Quienes lo logran suelen portar una orbe encantada que invoca la rabia requerida por cualquier buen demonio. No se sabe cómo ni quién hizo las orbes."}
MultiLanguageSpellData['mx'][196484] = {name = "Camisote Dientejauría", additional_info = "Hechizo de 2 seg 5\n[q]Una enorme pechera de mallas, creada totalmente con dientes de sabuesos demoniacos. Las puntas de los dientes miran hacia arriba y hacia adentro, lo que hace casi imposible quitársela una vez puesta; o sea, es imposible hacerlo sin rasgar la piel de quien la use."}
MultiLanguageSpellData['mx'][196485] = {name = "Peletería de fuerza", additional_info = nil}
MultiLanguageSpellData['mx'][196487] = {name = "Renovar purificado", additional_info = "[q]Si eliminas los efectos dañinos con Purificar, el objetivo recibirá Renovación purificada, lo que lo sanará al instante durante ([6.875% of Spell Power]), y 16 p. durante 8 s."}
