MultiLanguageSpellData['mx'][207219] = {name = "Seguidor: El Rey Mono", additional_info = "Instante\n[q]El Rey Mono era el fiel compañero de Shaohao, emperador de todo Pandaria. Es travieso, astuto y conoce incontables secretos acerca del pasado de Pandaria."}
MultiLanguageSpellData['mx'][207220] = {name = "Seguidor: Angus Puño de Hierro", additional_info = "Instante\n[q]Angus Puño de Hierro vino a este mundo con el deseo de pelear. Le encanta enfrentarse con cualquier rival y puede derrotarlo con una combinación de combate marcial, agarres, lucha y puños y patadas oportunos."}
