MultiLanguageSpellData['mx'][207222] = {name = "Seguidor: Hiro", additional_info = "Instante\n[q]Hiro ha vagado por el mundo durante muchos años, tambaleándose de una taberna a la siguiente, en la búsqueda de su próximo trago. Que no te engañe su apariencia desaliñada: no solo tiene un corazón de oro, sino que además entre más ha bebido, mejor pelea."}
MultiLanguageSpellData['mx'][207223] = {name = "Seguidor: Sylara Canto férreo", additional_info = "Instante\n[q]Sylara Corazón de Sombras es una vagabunda misteriosa que rara vez habla sobre su pasado. Solo hay una cosa clara, nada la enoja más que la injusticia. Todo el que se cruce en su camino recibe una prueba de sus espadas gemelas."}
MultiLanguageSpellData['mx'][207224] = {name = "Quest Credit", additional_info = nil}
MultiLanguageSpellData['mx'][207225] = {name = "Seguidor: Aegira", additional_info = "Instante\n[q]Aegira es una maestra cervecera vrykul, favorecida por el mismísimo Odyn. Sus brebajes son legendarios. Lo que los demás no saben es que sus habilidades de combate son formidables. Creció en el campo de batalla, y nadie que la haya desafiado ha podido derrotarla."}
