MultiLanguageSpellData['mx'][207235] = {name = "Seguidor: Celestos", additional_info = "Instante\n[q]El consular Celestos es uno de los elementales más antiguos y venerados dentro de Muro Celeste.\n\n Durante el reinado de Al'akir, Celestos fue consultor y estratega en jefe en muchas de las campañas del Señor del viento."}
MultiLanguageSpellData['mx'][207236] = {name = "Seguidor: Nobundo", additional_info = "Instante\n[q]El clarividente Nobundo fue el primero de los suyos en convertirse en chamán y aprender el camino de los elementos.\n\n Es uno de los chamanes más sabios del Anillo de la Tierra, y el líder anterior de la orden."}
MultiLanguageSpellData['mx'][207237] = {name = "Seguidor: Rehgar Furiatierra", additional_info = "Instante\n[q]Rehgar Furiatierra es un poderoso chamán elemental y antiguo gladiador que domina los caminos del combate.0$bHay pocos miembros del Anillo de la Tierra que pueden igualar la experiencia y la destreza de Rehgar en el campo de batalla."}
MultiLanguageSpellData['mx'][207238] = {name = "Seguidor: Scaldius", additional_info = "Instante\n[q]Barón Scaldius, un antiguo teniente de Ragnaros, ahora sirve al Señor del Fuego con una lealtad inquebrantable.0$bCon el poder y la furia de las Tierras de Fuego bajo sus órdenes, el Barón Scaldius incinerará a todos los enemigos que se crucen en su camino."}
MultiLanguageSpellData['mx'][207239] = {name = "Seguidor: Avalanchion", additional_info = "Instante\n[q]Entre los grandes Señores de piedra de Infralar, Avalanchion es conocido por ser prácticamente indestructible.0$bAvalanchion ignora fácilmente las sensaciones mortales como el miedo y el dolor, y cumplirá las órdenes de su amo con una concentración inquebrantable."}
MultiLanguageSpellData['mx'][207240] = {name = "Seguidor: Muln Furiatierra", additional_info = "Instante\n[q]Un antiguo líder de los Anillo de la Tierra, Muln Furiatierra es uno de los chamanes más grandes de su generación.0$bSu imponente presencia en el campo de batalla y su maestría en las \"formas antiguas\" de chamanismo lo convierten en un aliado valioso."}
