MultiLanguageSpellData['mx'][215116] = {name = "Campeón: Sombra de Akama", additional_info = "Instante\n[q]Como maestro arquitecto del plan de Illidan para destruir a la Legión Ardiente, y a la cabeza de la tribu Lengua de Ceniza, Akama demostró ser un diestro líder, como también un estratega brillante y un hábil peleador. Su Sombra es todo eso y mucho más."}
