MultiLanguageSpellData['mx'][215128] = {name = "Sangre maldita", additional_info = "Rango ilimitado\nInstante\n[q]Infecta la sangre de los jugadores con energía de Pesadilla, lo que inflige 865 p. de daño de las Sombras cada 2 s durante 8 s. Cuando este efecto termina, el jugador estalla e inflige 3959 p. de daño de las Sombras a los jugadores en un radio de 11 m."}
MultiLanguageSpellData['mx'][215129] = {name = "Campeón: Altruis el Sufridor", additional_info = "Instante\n[q]Cuando nadie se hubiera opuesto al método de Illidan para pelear contra la Legión Ardiente sin temer a las consecuencias, allí estuvo Altruis. Es el cazador de demonios más fuerte jamás visto. Sus habilidades de pelea solo pueden compararse con su agudo intelecto y el respeto que se ha ganado por impulsar el cambio en los métodos de los Illidari."}
