MultiLanguageSpellData['mx'][217650] = {name = "[q3]Tomo de ilusiones: Pandaria", additional_info = "Hechizo de 3.5 seg\nHerramientas: Vara de encantamiento con runas\nComponentes:\nCristal de sha (10), Amatista imperial (2), Jade salvaje (2), Ónice bermellón (2), Papiro ligero (3)\n[q]Crea un Tomo de ilusiones: Pandaria.\nProfesión:\nEncantamiento de Pandaria (50)\nInstructora:\nLai Zarpa Hechicera\nZona:\nEl Bosque de Jade\nCosto:\n2\n\n[q3]Tomo de ilusiones: Pandaria\n[q2]Uso: Reúne las apariencias de los encantamientos de armas de Son del viento, Fuerza elemental y Aliento de Yu'lon.\nNecesitas ser de nivel 32"}
MultiLanguageSpellData['mx'][217651] = {name = "[q3]Tomo de ilusiones: Secretos de Shadopan", additional_info = "Hechizo de 3.5 seg\nHerramientas: Vara de encantamiento con runas\nComponentes:\nCristal de sha (10), Corazón de río (2), Rubí primordial (2), Resplandor solar (2), Papiro ligero (3)\n[q]Crea un Tomo de ilusiones: Secretos del Shadopan.\nVendedor:\nRushi el Zorro\nZona:\nEstepas de Tong Long\nShadopan - Exaltado\nCosto:\n40\n\n[q3]Tomo de ilusiones: Secretos de Shadopan\n[q2]Uso: Reúne las apariencias de los encantamientos de arma de Canto del río y Acero danzante.\nNecesitas ser de nivel 32"}
